PRAGMA foreign_keys = OFF;
PRAGMA journal_mode  = WAL;
PRAGMA synchronous   = NORMAL;
PRAGMA cache_size    = -32000;
PRAGMA temp_store    = MEMORY;

BEGIN TRANSACTION;

-- ────────────────────────────────────────────────────────────
-- SCHÉMA
-- ────────────────────────────────────────────────────────────

-- TABLE : users
DROP TABLE IF EXISTS users;
CREATE TABLE users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      matricule TEXT,
      nom TEXT,
      prenom TEXT,
      actif BOOLEAN,
      pole TEXT,
      direction TEXT,
      departement TEXT,
      service TEXT,
      poste TEXT,
      activeDirectory TEXT UNIQUE,
      responsable1 TEXT,
      responsable2 TEXT,
      responsable3 TEXT,
      categorie TEXT,
      dateRecrutement TEXT,
      email TEXT,
      role TEXT
    , password TEXT, evalType TEXT, anonymized INTEGER DEFAULT 0, anonymizedAt TEXT, mustChangePassword INTEGER DEFAULT 1, photo TEXT);

-- TABLE : delegations
DROP TABLE IF EXISTS delegations;
CREATE TABLE delegations (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      targetUserId INTEGER,
      delegatedToUserId INTEGER,
      delegatedByUserId INTEGER,
      createdAt DATETIME DEFAULT CURRENT_TIMESTAMP
    );

-- TABLE : history_logs
DROP TABLE IF EXISTS history_logs;
CREATE TABLE history_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      actorId INTEGER,
      actorName TEXT,
      actorRole TEXT,
      department TEXT,
      type TEXT,
      action TEXT,
      target TEXT,
      toTarget TEXT,
      createdAt DATETIME DEFAULT CURRENT_TIMESTAMP
    );

-- TABLE : evaluations
DROP TABLE IF EXISTS evaluations;
CREATE TABLE evaluations (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      targetUserId INTEGER,
      evaluatorId INTEGER,
      type TEXT,
      ratings TEXT,
      tasks TEXT,
      strengths TEXT,
      weaknesses TEXT,
      trainingNeeds TEXT,
      recommendation TEXT,
      otherData TEXT,
      globalScore REAL,
      createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, status TEXT DEFAULT 'Soumise', rhComment TEXT, validatedAt TEXT, validatedBy INTEGER, rhFinalScore REAL, campaignYear INTEGER, rhDecision TEXT,
      FOREIGN KEY(targetUserId) REFERENCES users(id),
      FOREIGN KEY(evaluatorId) REFERENCES users(id)
    );

-- TABLE : notifications
DROP TABLE IF EXISTS notifications;
CREATE TABLE notifications (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      userId INTEGER NOT NULL,
      message TEXT NOT NULL,
      type TEXT DEFAULT 'info',
      read INTEGER DEFAULT 0,
      createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, link TEXT,
      FOREIGN KEY(userId) REFERENCES users(id)
    );

-- TABLE : feedback_360
DROP TABLE IF EXISTS feedback_360;
CREATE TABLE feedback_360 (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      targetUserId INTEGER NOT NULL,
      requestedBy INTEGER NOT NULL,
      respondentId INTEGER NOT NULL,
      message TEXT DEFAULT '',
      status TEXT DEFAULT 'pending',
      ratings TEXT,
      comment TEXT,
      globalScore REAL,
      createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,
      submittedAt DATETIME,
      FOREIGN KEY(targetUserId) REFERENCES users(id),
      FOREIGN KEY(requestedBy) REFERENCES users(id),
      FOREIGN KEY(respondentId) REFERENCES users(id)
    );

-- TABLE : app_settings
DROP TABLE IF EXISTS app_settings;
CREATE TABLE app_settings (
      key TEXT PRIMARY KEY,
      value TEXT
    );

-- TABLE : rgpd_audit_log
DROP TABLE IF EXISTS rgpd_audit_log;
CREATE TABLE rgpd_audit_log (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      action TEXT NOT NULL,
      targetUserId INTEGER,
      targetNameSnapshot TEXT,
      performedBy INTEGER,
      performedByName TEXT,
      details TEXT,
      performedAt DATETIME DEFAULT CURRENT_TIMESTAMP
    );

-- ────────────────────────────────────────────────────────────
-- INDEX
-- ────────────────────────────────────────────────────────────

CREATE INDEX idx_evals_created  ON evaluations(createdAt);
CREATE INDEX idx_evals_evaluator ON evaluations(evaluatorId);
CREATE INDEX idx_evals_status   ON evaluations(status);
CREATE INDEX idx_evals_target   ON evaluations(targetUserId);
CREATE INDEX idx_evals_year     ON evaluations(campaignYear);
CREATE INDEX idx_notif_user     ON notifications(userId);
CREATE INDEX idx_users_actif    ON users(actif);
CREATE INDEX idx_users_resp1    ON users(responsable1);

